impl<S: BosStr> LexiconSchema for Condition<S> {
    fn nsid() -> &'static str {
        "net.anisota.spell.custom"
    }
    fn def_name() -> &'static str {
        "condition"
    }
    fn lexicon_doc() -> LexiconDoc<'static> {
        lexicon_doc_net_anisota_spell_custom()
    }
    fn validate(&self) -> Result<(), ConstraintError> {
        if let Some(values) = &self.metrics {
            for value in values {
                #[allow(unused_comparisons)]
                if <str>::len(value.as_ref()) > 64usize {
                    return Err(ConstraintError::MaxLength {
                        path: ValidationPath::from_field("metrics"),
                        max: 64usize,
                        actual: <str>::len(value.as_ref()),
                    });
                }
            }
        }
        {
            let value = &self.variable;
            #[allow(unused_comparisons)]
            if <str>::len(value.as_ref()) > 64usize {
                return Err(ConstraintError::MaxLength {
                    path: ValidationPath::from_field("variable"),
                    max: 64usize,
                    actual: <str>::len(value.as_ref()),
                });
            }
        }
        if let Some(values) = &self.words {
            for value in values {
                #[allow(unused_comparisons)]
                if <str>::len(value.as_ref()) > 100usize {
                    return Err(ConstraintError::MaxLength {
                        path: ValidationPath::from_field("words"),
                        max: 100usize,
                        actual: <str>::len(value.as_ref()),
                    });
                }
            }
        }
        Ok(())
    }
}

